svg.script:
//!export-start
let _ps_selectedDb = "";
let _ps_selectedTable = "";
//!export-end

function setOptions(select, placeholder, values) {
  select.replaceChildren(new Option(placeholder, ""));
  values.forEach(value => select.add(new Option(value, value)));
}

function putValue(id, value) {
  if (id === "_ps_selectedDb") {
    _ps_selectedDb = value == null ? "" : value;
    const select = document.getElementById("databaseSelect");
    if (select && select.value !== _ps_selectedDb) {
      select.value = _ps_selectedDb;
      loadTables();
    }
  }

  if (id === "_ps_selectedTable") {
    _ps_selectedTable = value == null ? "" : value;
    const select = document.getElementById("tableSelect");
    if (select) select.value = _ps_selectedTable;
  }
}

async function getJson(url) {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error("Request failed with HTTP " + response.status);
  }
  return response.json();
}

async function loadTables() {
  const databaseSelect = document.getElementById("databaseSelect");
  const tableSelect = document.getElementById("tableSelect");
  const database = databaseSelect.value;
  _ps_selectedDb = database;
  _ps_selectedTable = "";
  tableSelect.disabled = true;

  if (typeof postValue === "function") {
    postValue("_ps_selectedDb", database);
    postValue("_ps_selectedTable", "");
  }

  if (!database) {
    setOptions(tableSelect, "Select a database first...", []);
    return;
  }

  setOptions(tableSelect, "Loading tables...", []);
  try {
    const tables = await getJson(
      new URL("api/dbexplorer/tables?db=" + encodeURIComponent(database), document.baseURI)
    );
    if (!Array.isArray(tables) || !tables.every(table => typeof table === "string")) {
      throw new Error("Table endpoint returned an invalid response");
    }
    setOptions(tableSelect, tables.length ? "Select a table..." : "No tables found", tables);
    if (tables.includes(_ps_selectedTable)) {
      tableSelect.value = _ps_selectedTable;
    }
    tableSelect.disabled = tables.length === 0;
  } catch (error) {
    console.error("[PostgreSQL database select] Unable to load tables:", error);
    setOptions(tableSelect, "Unable to load tables", []);
  }
}

async function init() {
  const select = document.getElementById("databaseSelect");
  const tableSelect = document.getElementById("tableSelect");
  if (!select || !tableSelect) return;

  select.addEventListener("change", loadTables);
  tableSelect.addEventListener("change", function() {
    _ps_selectedTable = tableSelect.value;
    if (typeof postValue === "function") {
      postValue("_ps_selectedTable", _ps_selectedTable);
    }
  });

  try {
    const databases = await getJson(new URL("api/dbexplorer/databases", document.baseURI));
    if (!Array.isArray(databases) || !databases.every(database => typeof database === "string")) {
      throw new Error("Database endpoint returned an invalid response");
    }
    const previous = databases.includes(_ps_selectedDb) ? _ps_selectedDb : "";
    setOptions(select, "Select a database...", databases);
    if (previous) select.value = previous;
    await loadTables();
  } catch (error) {
    console.error("[PostgreSQL database select] Unable to load databases:", error);
    select.replaceChildren(new Option("Unable to load databases", ""));
  }
}

init();
